import sys
from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes_data):
    if not nodes_data:
        return None
    root = Node(nodes_data[0])
    queue = deque([root])
    i = 1
    while queue and i < len(nodes_data):
        current = queue.popleft()
        if i < len(nodes_data) and nodes_data[i] is not None:
            current.left = Node(nodes_data[i])
            queue.append(current.left)
        i += 1
        if i < len(nodes_data) and nodes_data[i] is None:
            pass
        elif i < len(nodes_data):
            current.right = Node(nodes_data[i])
            queue.append(current.right)
        i += 1
    return root

def isCompleteBT(root):
    if root is None:
        return True
    queue = deque([root])
    found_null = False
    while queue:
        node = queue.popleft()
        if node is None:
            found_null = True
        else:
            if found_null:
                return False
            queue.append(node.left)
            queue.append(node.right)
    return True

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        parts = list(map(str.strip, line.split(',')))
        nodes_data = []
        for p in parts:
            if p.lower() == 'null':
                nodes_data.append(None)
            else:
                nodes_data.append(int(p))

        if not nodes_data:
            print("Complete Binary Tree")
            return

        root = build_tree(nodes_data)
        if isCompleteBT(root):
            print("Complete Binary Tree")
        else:
            print("Not Complete Binary Tree")
    except Exception:
        print("Not Complete Binary Tree")

if __name__ == "__main__":
    main()
